import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";

export default function Home() {
  const [data, setData] = useState(null);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => setData(res.data))
      .catch((err) => console.error(err));
  }, []);

  if (!data) return <p>Loading...</p>;

  return (
    <main className="home-container">
      {/* Banner */}
      {data.bannerVideos?.length > 0 && (
        <section className="banner-section">
          <video
            className="banner-video"
            src={`http://localhost:5000${data.bannerVideos[0]}`}
            controls
            autoPlay
            loop
            muted
          />
        </section>
      )}

      {/* Welcome + Activities */}
      <section className="welcome-activities-container">
        {/* Left: Welcome text */}
        <div
          className="welcome-text"
          dangerouslySetInnerHTML={{ __html: data.welcomeText }}
        ></div>

        {/* Right: Activities slider */}
        <div className="activities-slider-container">
          <h3>🏫 School Activities</h3>
          <div className="activities-slider">
            {data.activities?.length > 0 ? (
              data.activities.map((img, i) => (
                <div className="activity-slide" key={i}>
                  <img
                    src={`http://localhost:5000${img}`}
                    alt={`activity-${i}`}
                  />
                </div>
              ))
            ) : (
              <p>No activities uploaded yet</p>
            )}
          </div>
        </div>
      </section>

      {/* Testimonials */}
      {data.testimonialVideos?.length > 0 && (
        <section className="testimonials">
          <h2>🎬 Student Testimonials</h2>
          <div className="testimonial-grid">
            {data.testimonialVideos.map((vid, i) => (
              <video
                key={i}
                src={`http://localhost:5000${vid}`}
                controls
                className="testimonial-video"
              />
            ))}
          </div>
        </section>
      )}
    </main>
  );
}
